/** Logo del banco dentro de un círculo con el color de la marca en un tono
 *  muy claro. Devuelve `null` para el valor «all» (no es un banco real). */
export function BankLogo({ bank, size = 14, className }: { bank: BankId | 'all'; size?: number; className?: string }) {
  const gradientId = useId();
  if (bank === 'all') return null;
  const config = BANK_LOGOS[bank];
  const pad = Math.max(2, Math.round(size * 0.32));
  const circle = size + pad * 2;
  return (
    <span
      className={`inline-flex items-center justify-center flex-shrink-0 rounded-full ${className ?? ''}`}
      style={{ backgroundColor: config.bg, width: `${circle}px`, height: `${circle}px` }}
      aria-hidden="true"
    >
      <svg
        width={size}
        height={size}
        viewBox={config.viewBox}
        preserveAspectRatio="xMidYMid meet"
        xmlns="http://www.w3.org/2000/svg"
        className="block"
      >
        {config.icon(gradientId)}
      </svg>
    </span>
  );
}